              to: String.raw`\int_{\T{lim-1}{0}}^{\T{lim-2}{8}} \frac{\T{du-1}{3u^2\,\mathrm d u}}{1 + \T{u-1}{u}}`, arrows: { 'u-1': '∛x = u', 'du-1': 'dx' },
